def calculate_average_unemployment_ratio(df):
    avg_1995 = df['A2'].mean()
    avg_1996 = df['A3'].mean()

    if avg_1995 > avg_1996:
        return "1995"
    elif avg_1995 < avg_1996:
        return "1996"
    else:
        return "Both years have the same average unemployment ratio"

