def calculate_unemployment_ratio():
    # Calculate the average unemployment ratio for 1995 and 1996
    avg_1995 = district[district['A1'] == '1995']['A2'].astype(float).mean()
    avg_1996 = district[district['A1'] == '1996']['A2'].astype(float).mean()

    # Compare the averages and return the result
    if avg_1995 > avg_1996:
        return "1995"
    else:
        return "1996"

def compare_unemployment_ratio(df):
    avg_1995 = df['A2'].mean()
    avg_1996 = df['A3'].mean()
    if avg_1995 > avg_1996:
        return "1995"
    else:
        return "1996"

