def find_district_of_female_client(client_df, district_df):
    female_client = client_df[(client_df['gender'] == 'female') & (client_df['birth_date'] == '1976/1/29')]
    if not female_client.empty:
        district_id = female_client['district_id'].iloc[0]
        district_info = district_df[district_df['district_id'] == district_id]
        return district_info[['A2', 'A3', 'A4', 'A5', 'A6', 'A7', 'A8', 'A9', 'A10', 'A11', 'A12', 'A13', 'A14', 'A15', 'A16']]
    else:
        return None

def get_client_district(gender, birth_date):
    filtered_clients = client[(client['gender'] == gender) & (client['birth_date'] == birth_date)]
    if not filtered_clients.empty:
        district_id = filtered_clients.iloc[0]['district_id']
        return district.loc[district['district_id'] == district_id, ['A2', 'A3', 'A4', 'A5', 'A6', 'A7', 'A8', 'A9', 'A10', 'A11', 'A12', 'A13', 'A14', 'A15', 'A16']].values.flatten()
    else:
        return None

