def count_non_credit_card_holders(df_district, df_client, df_disp, df_account):
    south_bohemian_accounts = df_account[df_account['district_id'] == 'South Bohemia']
    non_credit_card_accounts = south_bohemian_accounts[south_bohemian_accounts['type'] != 'credit card']
