def count_male_clients_in_hl_praha(client_df, district_df):
    hl_praha_mask = district_df['district_id'] == 'Hl.m. Praha'
    hl_praha_district = district_df[hl_praha_mask]
    client_ids_in_hl_praha = hl_praha_district['client_id']

    male_clients_in_hl_praha = client_df[(client_df['client_id'].isin(client_ids_in_hl_praha)) & (client_df['gender'] == 'male')]

    return len(male_clients_in_hl_praha)

def get_credit_card_type(client_id):
    # Join the relevant tables to find the card type for the given client ID
    result = pd.merge(card, disp, on='disp_id')
    result = pd.merge(result, client, on='client_id')
    filtered_result = result[result['client_id'] == client_id]
    return filtered_result['type'].unique()

def get_credit_card_type(client_id):
    client_disp = client[client['client_id'] == client_id]['disp_id'].values[0]
    card_info = card[card['disp_id'] == client_disp]
    return card_info['type'].unique()

def get_order_placer(order_id):
    query = f"SELECT T1.account_id FROM order AS T1 JOIN client AS T2 ON T1.account_id = T2.account_id WHERE T1.order_id = {order_id}"
    return pd.read_sql(query, con=engine)['account_id'].iloc[0]

def find_order_placer(order_id):
