def count_credit_card_withdrawals_after_1995(trans):
    # Filter transactions for credit card withdrawals and after 1995
    filtered_transactions = trans[(trans['type'] == 'VYBER') & (trans['date'].str.contains(r'/96/'))]
    # Count the number of such transactions
    return len(filtered_transactions)

